def _record_resume_artifacts(
    run: PipelineRun,
    completed_stages: Sequence[str],
) -> None:
    checksums = dict(
        (run.extra.get("resume") or {}).get("artifact_checksums") or {}
    )
    for stage in completed_stages:
        for path in _stage_artifacts(run, stage):
            if path.is_file():
                relative = str(path.relative_to(run.run_path))
                checksum = sha256_file(path)
                checksums[relative] = checksum
                record_artifact(
                    run,
                    relative.replace("/", "_"),
                    local_path=path,
                    checksum=checksum,
                    persist=False,
                )
    update_resume_state(
        run,
        requested_from_stage=None,
        completed_stages=completed_stages,
        artifact_checksums=checksums,
    )


def run_pipeline(options: RunnerOptions) -> PipelineExecutionResult:
    """Execute an ordered, resumable Pipeline V2 stage plan."""
    config, run, clinical_paths = prepare_run_context(options)
    plan = resolve_stage_plan(options, config)
    if options.dry_run:
        return PipelineExecutionResult(
