def _save_score_plot(table: pd.DataFrame, output: Path) -> Path:
    figure, axis = plt.subplots(figsize=(9.5, 4.2))
    y = np.arange(len(table))
    colors = ["#d62728" if "study_group" in factor else "#1f77b4" for factor in table["factor"]]
    axis.barh(y, table["rbc"].fillna(0), color=colors)
    axis.axvline(0, color="black", linewidth=0.8)
    axis.set_yticks(y)
    axis.set_yticklabels(
        [
            f"{factor}\n|RBC|={abs(rbc):.3f} p={p_value:.3g}"
            if pd.notna(rbc)
            else factor
            for factor, rbc, p_value in zip(
                table["factor"], table["rbc"], table["p"], strict=True
            )
        ],
        fontsize=8,
    )
    axis.set_xlabel("Rank-biserial correlation on patient score")
    axis.set_title("Score separation: study group versus blip/date factors")
    figure.tight_layout()
    figure.savefig(output, dpi=140, bbox_inches="tight")
    plt.close(figure)
    return output


