def _normalize_group(value) -> str:
    try:
        numeric = float(value)
        if numeric == 2:
            return pos_label
        if numeric == 1:
            return neg_label
    except Exception:
        pass
    text = str(value)
    # Accept already-named labels case-insensitively.
    if text.upper() == str(pos_label).upper():
        return pos_label
    if text.upper() == str(neg_label).upper():
        return neg_label
    return text

