def _categorize_accuracy(val: float, *, low: float, high: float) -> str:
    """Determine if a value is in the greyzone based on accuracy rate."""
    if pd.isna(val):
        return "grayzone"
    if low == high and val == low:
        return "non_grayzone"
    if low <= val <= high:
        return "grayzone"
    return "non_grayzone"


def _categorize_accuracy_rate(val: float, *, low: float, high: float) -> str:
    """Categorize accuracy rate into correct/incorrect/grayzone buckets."""
    if pd.isna(val):
        return "grayzone"
    if val > high:
        return "correct"
    if val < low:
        return "incorrect"
    return "grayzone"


