meta = unit_df[["unit_number", "unit_type"]].drop_duplicates()
unit_type_values = sorted(meta["unit_type"].dropna().astype(str).unique().tolist())
unit_type_display = unit_type_values[0] if len(unit_type_values) == 1 else ", ".join(unit_type_values) or "N/A"

warnings: List[str] = []
if len(unit_type_values) > 1:
    warnings.append("unit_type is not unique for this unit_number.")

channel_rows: List[Dict[str, object]] = []
sensor_types_for_legend: List[str] = []

for channel in range(1, 33):
    sensor_type = _dominant_sensor_type(
        slot_df.loc[slot_df["device_channel"] == channel, "sensor_type"]
    )
    sensor_types_for_legend.append(sensor_type)
    channel_rows.append(
        {
            "channel": channel,
            "sensor_type": sensor_type,
        }
    )

color_map = _sensor_color_map(sensor_types_for_legend)
slot_summary_html = _channel_sensor_summary_tables_html(channel_rows, color_map)

metadata_df = pd.DataFrame(
    [
        {
            "unit_number": str(unit_number),
            "unit_type": unit_type_display,
            "rows_in_report": len(unit_df),
            "unique_patients": unit_df["Patient_Id"].nunique(),
            "date_range": f"{unit_df['file_write_time'].min()}  ->  {unit_df['file_write_time'].max()}",
        }
    ]
)

legend_items = []
for sensor, color in sorted(color_map.items(), key=lambda x: x[0]):
    legend_items.append(
        f'<div class="legend-item"><span class="legend-dot" style="background:{escape(color)};"></span>{escape(sensor)}</div>'
    )

warning_html = ""
if warnings:
    warning_html = "<div class='warning-box'>" + "<br>".join(escape(w) for w in warnings) + "</div>"

fw_time_matrix_html = _build_file_write_time_matrix_html(unit_df, pcb_col)
# unit_df.to_csv('tempUnitdf.csv', index=False)

